using System.Text.Json;using ArchLucid.Contracts.Drafts;namespace ArchLucid.Persistence.Data.Repositories;internal static class DraftRequestRepositoryCore{public const int MaxPriorDraftsCap=25;public const int MaxReaperBatchSize=10000;public static int ClampReaperBatchSize(int b)=>Math.Clamp(b,1,MaxReaperBatchSize);public static int ClampPriorDraftsMaxCount(int m)=>Math.Clamp(m,1,MaxPriorDraftsCap);public static string NormalizeSystemName(string s){ArgumentException.ThrowIfNullOrWhiteSpace(s);return s.Trim().ToUpperInvariant();}public static DraftRequestDocument CloneDocument(DraftRequestDocument d,JsonSerializerOptions o){ArgumentNullException.ThrowIfNull(d);ArgumentNullException.ThrowIfNull(o);return JsonSerializer.Deserialize<DraftRequestDocument>(JsonSerializer.Serialize(d,o),o)??throw new InvalidOperationException();}public static DraftRequestStatus ParseStatus(string s,Guid id){ArgumentException.ThrowIfNullOrWhiteSpace(s);if(!Enum.TryParse(s,true,out DraftRequestStatus p))throw new InvalidOperationException();return p;}public static DraftRequestDocument DeserializeDocument(string j,Guid id,JsonSerializerOptions o){ArgumentException.ThrowIfNullOrWhiteSpace(j);ArgumentNullException.ThrowIfNull(o);return JsonSerializer.Deserialize<DraftRequestDocument>(j,o)??throw new InvalidOperationException();}public static DraftRequestResponse MapToResponse(Guid draftId,Guid tenantId,Guid workspaceId,Guid projectId,DraftRequestStatus status,DraftRequestDocument document,string? redirectReason,string? spawnedRunId,string createdByUserId,DateTime createdUtc,DateTime updatedUtc){ArgumentNullException.ThrowIfNull(document);ArgumentException.ThrowIfNullOrWhiteSpace(createdByUserId);return new DraftRequestResponse{DraftId=draftId,TenantId=tenantId,WorkspaceId=workspaceId,ProjectId=projectId,Status=status,Document=document,RedirectReason=redirectReason,SpawnedRunId=spawnedRunId,CreatedByUserId=createdByUserId,CreatedUtc=createdUtc,UpdatedUtc=updatedUtc};}}